/// Spiral's corner radii by role, in points.
///
/// Buttons and text fields are capsules, which take no number. Use `Capsule()`.
public enum SpiralRadius {
    /// Thumbnails and other small media.
    public static let thumbnail: CGFloat = 8
    /// A content block in a flow: a notice, a banner, a box.
    public static let block: CGFloat = 12
    /// A message bubble.
    public static let bubble: CGFloat = 16
    /// A call in the timeline: a bubble round its 38 pt disc (question 359).
    public static let callBubble: CGFloat = 24
    /// A card of list rows, and a card that sits on the screen's canvas like one, as iOS 26 rounds
    /// a grouped list's sections.
    public static let listCard: CGFloat = 26
    /// A group room's avatar: a rounded square, drawn continuous, at any avatar size (decision
    /// 357).
    public static func groupAvatar(side: CGFloat) -> CGFloat { side * 0.28 }
}

